    let file: File = File::open(&path)?;
    let reader: BufReader<File> = BufReader::new(file);

    // Read all lines into a vector to use with rayon
    let lines: Vec<String> = reader.lines().collect::<Result<_, _>>()?;

    // Estimate the capacity of the hashmap (depends on the expected number of lines)
    let initial_capacity = lines.len() as usize;

